function unique(items) {
  const out = [];
  for (const x of items) {
    if (out.indexOf(x)) out.push(x);
  }
  return out;
}

tasks.solution:
function unique(items) {
  const out = [];
  for (const x of items) {
    if (!out.includes(x)) out.push(x);
  }
  return out;
}

